<?php
$leadPackage = is_array($salesCrmData['lead_package'] ?? null) ? $salesCrmData['lead_package'] : [];
$appointments = is_array($leadPackage['appointments'] ?? null) ? $leadPackage['appointments'] : [];
$appointmentEditKey = trim((string) ($_GET['edit'] ?? ''));
$editAppointment = yovel_admin_find_record($appointments, 'appointment_key', $appointmentEditKey);
$appointmentState = (string) ($activeModuleFormState['action'] ?? '') === 'sales_crm_save_appointment' ? $activeModuleFormState : [];
$appointmentValues = array_merge(['appointment_status' => 'SCHEDULED'], $editAppointment ?: [], is_array($appointmentState['input'] ?? null) ? $appointmentState['input'] : []);
$appointmentFieldsBySection = [];
foreach ($visibleSchemaFields as $field) {
    $appointmentFieldsBySection[(string) ($field['section'] ?? 'schedule')][] = $field;
}
$settingsState = (string) ($activeModuleFormState['action'] ?? '') === 'sales_crm_save_appointment_settings' ? $activeModuleFormState : [];
$settingsValues = array_merge(is_array($leadPackage['appointment_settings'] ?? null) ? $leadPackage['appointment_settings'] : [], is_array($settingsState['input'] ?? null) ? $settingsState['input'] : []);
$slotState = (string) ($activeModuleFormState['action'] ?? '') === 'sales_crm_save_appointment_slot' ? $activeModuleFormState : [];
$slotValues = is_array($slotState['input'] ?? null) ? $slotState['input'] : [];
$availabilityDays = [];
for ($offset = 0; $offset < 7; $offset++) {
    $date = (new DateTimeImmutable('today'))->modify('+' . $offset . ' day')->format('Y-m-d');
    $slots = yovel_admin_sales_appointment_availability($company, $admin, $date);
    if ($slots) {
        $availabilityDays[] = ['date' => $date, 'slots' => $slots];
    }
}
?>
