le slots</h4></div><?php if (!$availabilityDays): ?><p class="p-4 text-xs text-muted-foreground">No available slots in the next seven days.</p><?php endif; ?><div class="divide-y"><?php foreach ($availabilityDays as $day): ?><section class="p-4"><h5 class="text-xs font-semibold"><?= bx_h((string) $day['date']) ?></h5><div class="mt-2 flex flex-wrap gap-2"><?php foreach ($day['slots'] as $slot): ?><span class="rounded-md bg-muted px-2 py-1 text-[11px]"><?= bx_h((string) $slot['start_time']) ?>-<?= bx_h((string) $slot['end_time']) ?></span><?php endforeach; ?></div></section><?php endforeach; ?></div></aside></div>

